//! Minimal re-implementation of the immer-style persistent vector API.
//!
//! Backed by a plain `Vec<T>`: every "persistent" update copies the
//! underlying storage, which preserves the value semantics of
//! `immer::vector` (the original vector is never mutated).
//! The transient variant mutates in place and can be frozen back into
//! a persistent vector.

#[derive(Clone)]
pub struct Vector<T: Clone> {
    data: Vec<T>,
}

impl<T: Clone> Vector<T> {
    pub fn new() -> Self {
        Vector { data: Vec::new() }
    }

    /// Returns a new vector with `value` appended; `self` is unchanged.
    pub fn push_back(&self, value: T) -> Self {
        let mut data = self.data.clone();
        data.push(value);
        Vector { data }
    }

    pub fn len(&self) -> usize {
        self.data.len()
    }

    /// Opens a mutable transient view of this vector.
    pub fn transient(&self) -> TransientVector<T> {
        TransientVector {
            data: self.data.clone(),
        }
    }
}

impl<T: Clone> std::ops::Index<usize> for Vector<T> {
    type Output = T;

    fn index(&self, index: usize) -> &Self::Output {
        &self.data[index]
    }
}

pub struct TransientVector<T: Clone> {
    data: Vec<T>,
}

impl<T: Clone> TransientVector<T> {
    /// Sets the element at `index`. Out-of-range indices are ignored
    /// (a transient set cannot grow the vector).
    pub fn set(&mut self, index: usize, value: T) {
        if index < self.data.len() {
            self.data[index] = value;
        }
    }

    pub fn push_back(&mut self, value: T) {
        self.data.push(value);
    }

    /// Freezes the transient back into a persistent vector.
    pub fn persistent(self) -> Vector<T> {
        Vector { data: self.data }
    }
}

