mod immer_vector;

use immer_vector::Vector;
use std::env;

fn main() {
    let args: Vec<String> = env::args().collect();
    let n: i32 = if args.len() > 1 {
        args[1].parse().expect("invalid integer argument")
    } else {
        14
    };

    let mut v = Vector::<i32>::new();
    for i in 0..n {
        v = v.push_back(i);
    }

    let mut t = v.transient();
    t.set((n / 2) as usize, n * 10);
    t.push_back(n * 20);
    t.push_back(n * 30);

    let v2 = t.persistent();

    println!("{} {}", v.len(), v2.len());
    println!("{}", v2[(n / 2) as usize]);

    // Mirror the C++ loop `for (int i = v2.size() - 3; i < v2.size(); ++i)`:
    // when size < 3 the signed start index is negative and, once converted
    // to size_t for the comparison, the loop body never runs.
    let size = v2.len() as i64;
    let start = size - 3;
    if start >= 0 {
        for i in start..size {
            print!("{} ", v2[i as usize]);
        }
    }
    println!();
}

